import Foundation

// Shared with the widget extension (target membership: Artura and ArturaWidget).
// Keep this file free of any app-only type.

/// Interface text in the app's language. The key is the English text; translations are in
/// `<code>.lproj/Localizable.strings`, generated by `catalog/translations/app/app.py`.
/// A missing translation shows the English.
func L(_ english: String) -> String {
    AppLanguage.bundle.localizedString(forKey: english, value: english, table: nil)
}

/// Same, with values: the key uses `%@` for each value, in order (translations may reorder with `%1$@`, `%2$@`).
/// Pass every value already formatted as text: `L("%@ lessons", "\(count)")`.
func L(_ english: String, _ values: String...) -> String {
    let format = AppLanguage.bundle.localizedString(forKey: english, value: english, table: nil)
    return String(format: format, locale: AppLanguage.locale, arguments: values.map { $0 as CVarArg })
}

extension Notification.Name {
    /// Posted when the language is changed from inside the app (onboarding).
    static let appLanguageChanged = Notification.Name("appLanguageChanged")
}

enum AppLanguage {
    /// The app's languages, in the order of the language lists.
    static let all = ["en", "fr", "es", "de", "pt-BR", "pt-PT", "it", "tr", "pl", "ro", "nl", "el", "sv", "hu", "bg",
                      "cs", "da", "nb", "ru", "hr", "sl", "sk", "sr-Latn", "ar", "he", "fi", "et", "lt", "lv", "ja"]

    /// Current language: "en", "fr", "pt-BR", "sr-Latn"… At launch, the one iOS chose for the app
    /// (Settings > Artura > Language, or the phone's language); then the one picked in the onboarding.
    private(set) static var code: String = Bundle.main.preferredLocalizations.first ?? "en"

    /// Where the translations of `code` are.
    private(set) static var bundle: Bundle = lproj(code)

    static var isEnglish: Bool { code == "en" || code.hasPrefix("en-") }

    /// For dates and numbers in the app's language.
    static var locale: Locale { Locale(identifier: code) }

    /// Right-to-left interface (Arabic, Hebrew).
    static var isRightToLeft: Bool { Locale.Language(identifier: code).characterDirection == .rightToLeft }

    /// Name of a language in that language: "Français", "Deutsch", "日本語"…
    static func name(of language: String) -> String {
        let own = Locale(identifier: language)
        let name = own.localizedString(forIdentifier: language) ?? language
        return String(name.prefix(1)).uppercased(with: own) + String(name.dropFirst())
    }

    /// Switches the whole app to `language` now, and keeps it for the next launches
    /// (iOS also shows it in Settings > Artura > Language).
    static func set(_ language: String) {
        guard all.contains(language), language != code else { return }
        let previous = code
        code = language
        Analytics.track("language_changed", ["from": previous, "to": language])
        bundle = lproj(language)
        UserDefaults.standard.set([language], forKey: "AppleLanguages")
        NotificationCenter.default.post(name: .appLanguageChanged, object: nil)
    }

    private static func lproj(_ language: String) -> Bundle {
        guard let path = Bundle.main.path(forResource: language, ofType: "lproj"),
              let bundle = Bundle(path: path) else { return .main }
        return bundle
    }

    /// Name of a bundled file for the current language, falling back to English: `content.fr.json`, then `content.json`.
    static func resource(_ name: String, _ ext: String) -> URL? {
        if !isEnglish, let url = Bundle.main.url(forResource: "\(name).\(code)", withExtension: ext) { return url }
        return Bundle.main.url(forResource: name, withExtension: ext)
    }
}
